const d=(s:string)=>`sha256:${s.repeat(64)}`,id=(prefix:string,s:string)=>`${prefix}_${s.repeat(32)}`,now='2026-10-12T10:00:00Z',seconds=Date.parse(now)/1000,expires=savedMSIFixture.session.expiresAt;
let actor='';
const devices=savedMSIFixture.devices as unknown as Device[];
let data:WorklistsView,artifact:ManagedArtifactView,caps:string[],clock:number;
const session=()=>({...savedMSIFixture.session,serverNow:new Date(clock*1000).toISOString(),capabilities:caps,actorId:actor});
const w=()=>data.worklists[0];
function reset(stage:WorklistKind='deliver'){
 const worklist=structuredClone(savedMSIFixture.worklist) as WorklistView;
 if(stage!=='deliver')for(const [i,row] of worklist.rows.entries()){if(!row.view)continue;const v=row.view,t=worklist.targets[i];t.transferId=id('transfer',String(i+1));t.jobSequence='1';Object.assign(v,{transferId:t.transferId,jobSequence:'1',state:stage==='review'?'imported':'ready',canReview:stage==='review',readinessDigest:stage==='approve'||stage==='schedule'?d('f'):'',expiresAt:stage==='approve'||stage==='schedule'?seconds+55:0,readiness:stage==='approve'||stage==='schedule'?{selection:v.package,capturedAt:seconds,packageVerified:'yes',machineAbsent:'yes',installerBusy:'no',nativeAcceptance:'yes',packageReviewAccepted:'yes',maintenanceWindowEnd:seconds+600}:null});if(stage==='schedule')Object.assign(v,{schedulingAvailable:true,leafExpiresAt:seconds+1800});row.state=v.state}
 if(stage==='retire')for(const [i,row] of worklist.rows.entries()){if(!row.view)continue;const v=row.view;Object.assign(v,{state:'complete',readiness:null,readinessDigest:'',expiresAt:seconds-300,canReview:false,canRetire:true,resultDigest:d(String(i+2)),result:{jobId:`software_${v.transferId.slice(9)}`,envelopeDigest:d('9'),attempted:true,returnCodeKnown:true,returnCode:i===0?1603:3010,outcome:i===0?'failed':'restart_required',registrationVerified:i===0?'no':'yes',completedAt:seconds-120}});row.state=v.state}
 data={version:worklistVersion,serverNow:seconds,enabled:true,worklists:[worklist]};artifact=structuredClone(savedMSIFixture.artifact) as ManagedArtifactView;
}
function preview(kind:WorklistKind,window={startAt:seconds+120,endAt:seconds+420}):WorklistPreview{return {worklistId:w().id,revision:w().revision,kind,items:w().rows.filter(r=>r.available).map((row,index)=>({deviceId:row.deviceId,operation:kind==='review'?'review-coordinated':kind,artifactId:w().artifactId,artifactRetiredCount:w().artifactRetiredCount,bindingDigest:row.view!.bindingDigest!,transferId:kind==='deliver'?id('transfer',String(index+1)):row.view!.transferId,jobSequence:kind==='deliver'?'':row.view!.jobSequence!,readinessDigest:kind==='approve'||kind==='schedule'?row.view!.readinessDigest:'',expiresAt:kind==='approve'||kind==='schedule'?row.view!.expiresAt:seconds+60,...(kind==='schedule'?window:{}),...(kind==='retire'?{resultDigest:row.view!.resultDigest}: {})})),excluded:w().rows.filter(r=>!r.available).map(r=>({deviceId:r.deviceId,reason:'unavailable'}))}}
function createBatch(p:WorklistPreview){const b:WorklistBatch={id:id('batch','a'),kind:p.kind,actorId:actor,sessionDigest:d('7'),sessionExpiresAt:Date.parse(expires)/1000,createdAt:seconds,expiresAt:Math.min(seconds+60,...p.items.map(q=>q.expiresAt)),closedAt:0,closeReason:'',confirmationDigest:d('8'),acknowledgements:worklistAcknowledgements(p.kind),items:p.items.map(request=>({request,state:'not_dispatched',issuedAt:0,permitDigest:'',jobSequence:'0'}))};w().batches.push(b);w().revision++;return b}
function issue(index:number){const b=w().batches.at(-1)!,q=b.items[index].request,target=w().targets[index],view=w().rows[index].view!;target.transferId=q.transferId;target.jobSequence='1';Object.assign(view,{transferId:q.transferId,jobSequence:'1',state:b.kind==='deliver'?'delivery_pending':b.kind==='review'?'readiness_pending':b.kind==='retire'?'retirement_pending':'approved',canReview:false,...(b.kind==='retire'?{canRetire:false}: {})});w().rows[index].state=view.state;Object.assign(b.items[index],{state:'issued',issuedAt:seconds,permitDigest:d('6'),jobSequence:'1'});if(index===b.items.length-1){b.closedAt=seconds;b.closeReason='finished'}w().revision++;return structuredClone(view)}
async function issueScheduled(index:number){const b=w().batches.at(-1)!,q=b.items[index].request,view=w().rows.find(r=>r.deviceId===q.deviceId)!.view!,body=worklistDispatchBody(w(),b,index);view.schedule={version:'tracebolt.windows-managed-msi-schedule.v1',digest:d(String(index+2)),requestDigest:await managedScheduleRequestDigest(body as never),actorId:actor,approvedAt:seconds,startAt:q.startAt!,endAt:q.endAt!,readinessDigest:q.readinessDigest,state:'scheduled',readinessIssuedAt:0,permitIssuedAt:0,outcomeAt:0,canCancel:true};w().rows.find(r=>r.deviceId===q.deviceId)!.state='scheduled';Object.assign(b.items[index],{state:'scheduled',issuedAt:seconds,permitDigest:'',scheduleDigest:view.schedule.digest,jobSequence:q.jobSequence});if(index===b.items.length-1){b.closedAt=seconds;b.closeReason='finished'}w().revision++;return structuredClone(view)}
const flush=()=>act(async()=>{});
const mount=async()=>{const ui=render(<SavedManagedMSIWorklists actor={actor} expires={expires} artifact={artifact} devices={devices} onMode={()=>{}}/>);await flush();return ui};
const stage=async(kind:WorklistKind)=>{fireEvent.click(screen.getByRole('button',{name:kind==='deliver'?'Deliver selected devices':kind==='review'?'Review installations':kind==='retire'?'Review package cleanup':'Approve ready devices'}));await flush()};
const confirm=async()=>{fireEvent.click(screen.getByRole('checkbox'));fireEvent.click(screen.getByRole('button',{name:'Confirm exact requests'}));await flush()};
const mutations=()=>vi.mocked(mutateRaw).mock.calls.filter(([path])=>!path.endsWith('/preview')&&!path.endsWith('/schedule-preview'));
beforeEach(()=>{actor=`operator_${crypto.randomUUID().replaceAll('-','')}`;clock=seconds;caps=['read','windows_managed_msi_deliver','windows_managed_msi_install'];reset();setLocale('en',false);vi.useFakeTimers({toFake:['Date','performance','setTimeout','clearTimeout','setInterval','clearInterval']});vi.setSystemTime(now);vi.mocked(useOperator).mockReturnValue({...session(),theme:'light',logout:vi.fn(),setTheme:vi.fn()} as never);vi.mocked(request).mockReset().mockImplementation(async path=>structuredClone(path==='/auth/session'?session():path==='/windows-managed-msi/catalogue'?{version:'tracebolt.windows-managed-msi-catalogue.v1',enabled:false,serverNow:seconds,revision:'0',maxEntries:4,maxRetainedPayloadBytes:134217728,reservedBytes:0,entries:[]}:path===worklistPath?data:path==='/windows-managed-msi/artifact'?artifact:w().rows.find(row=>path.includes(row.deviceId))?.view) as never);vi.mocked(mutateRaw).mockReset().mockImplementation(async(path,raw,_headers,_signal,_maximum,beforeSend)=>{if(beforeSend&&!beforeSend())throw new DOMException('stopped','AbortError');const body=JSON.parse(raw);if(path.endsWith('/schedule-preview'))return structuredClone(preview('schedule',{startAt:body.startAt,endAt:body.endAt})) as never;if(path.endsWith('/preview'))return structuredClone(preview(body.kind)) as never;if(path.endsWith('/batches')){createBatch(body);return structuredClone(w()) as never}if(path.endsWith('/schedule'))return await issueScheduled(body.batch.item) as never;if(path.startsWith('/devices/'))return issue(body.batch.item) as never;if(path.endsWith('/close')){expect(body.revision).toBe(w().revision);const b=w().batches.at(-1)!;b.closedAt=seconds;b.closeReason='stopped';w().revision++;return structuredClone(w()) as never}if(path.endsWith('/archive')){w().archivedAt=seconds;w().rows=w().rows.map(r=>({deviceId:r.deviceId,available:false,state:'unavailable'}));w().revision++;return structuredClone(w()) as never}throw Error('unexpected mutation')})});
afterEach(()=>{cleanup();vi.useRealTimers();vi.restoreAllMocks()});
it('strictly validates identities, bounds, package occurrences and row availability',()=>{expect(validWorklistsView(data)).toBe(true);for(const change of [{targets:[...w().targets,...w().targets]},{artifactRetiredCount:'01'},{rows:[...w().rows].reverse()},{revision:0},{publisherStatus:'verified'},{unknown:true},{name:'x'.repeat(121)},{batches:Array(10).fill({})}])expect(validWorklistView({...w(),...change})).toBe(false);expect(validWorklistView({...w(),rows:[{...w().rows[0],available:false},...w().rows.slice(1)]})).toBe(false);const p=preview('deliver');expect(validWorklistPreview(p,w(),'deliver')).toBe(true);expect(validWorklistPreview({...p,items:[p.items[0],p.items[0]]},w(),'deliver')).toBe(false);expect(validWorklistPreview({...p,items:[{...p.items[0],artifactRetiredCount:'1'},p.items[1]]},w(),'deliver')).toBe(false)});
it('opening and reopening an open batch are GET-only and never resume or close',async()=>{createBatch(preview('deliver'));let ui=await mount();expect(screen.getByRole('button',{name:'Stop sending remaining requests'})).toBeEnabled();expect(mutateRaw).not.toHaveBeenCalled();ui.unmount();ui=await mount();expect(mutateRaw).not.toHaveBeenCalled();expect(screen.queryByRole('button',{name:'Confirm exact requests'})).toBeNull();ui.unmount()});
it.each(['deliver','review','approve','retire'] as const)('requires a new unchecked %s confirmation and dispatches only exact original bodies',async kind=>{reset(kind);await mount();await stage(kind);expect(mutations()).toHaveLength(0);expect(screen.getByRole('checkbox')).not.toBeChecked();expect(screen.getByRole('button',{name:'Confirm exact requests'})).toBeDisabled();const p=preview(kind);await confirm();expect(mutations().map(([path])=>path.split('/').at(-1))).toEqual(['batches',p.items[0].operation,p.items[1].operation]);for(let i=0;i<2;i++){const raw=JSON.parse(mutations()[i+1][1]);expect(raw).toEqual(worklistDispatchBody(w(),w().batches[0],i));for(const key of ['expiresAt','deviceId','operation'])expect(raw).not.toHaveProperty(key)}expect(screen.queryByRole('checkbox')).toBeNull()});
it('double confirmation clicks issue one batch and never progress another stage',async()=>{await mount();await stage('deliver');fireEvent.click(screen.getByRole('checkbox'));const button=screen.getByRole('button',{name:'Confirm exact requests'});fireEvent.click(button);fireEvent.click(button);await flush();expect(mutations()).toHaveLength(3);expect(mutations().filter(([path])=>path.endsWith('/batches'))).toHaveLength(1);expect(mutations().some(([path])=>path.endsWith('/review-coordinated')||path.endsWith('/approve'))).toBe(false)});
it.each(['blur','pagehide','popstate','hashchange',AUTH_REQUIRED_EVENT])('stops on %s and closes with the reconciled revision after a late issued item',async event=>{await mount();await stage('deliver');const original=vi.mocked(mutateRaw).getMockImplementation()!;let resolve!:(v:unknown)=>void;vi.mocked(mutateRaw).mockImplementation(async(path,...rest)=>path.startsWith('/devices/')?new Promise(r=>{resolve=r}) as never:original(path,...rest));await confirm();expect(mutations()).toHaveLength(2);act(()=>window.dispatchEvent(new Event(event)));await act(async()=>resolve(issue(0)));expect(mutations().map(([p])=>p.split('/').at(-1))).toEqual(['batches','deliver','close']);expect(w().batches[0].items.map(i=>i.state)).toEqual(['issued','not_dispatched']);expect(w().batches[0].closeReason).toBe('stopped')});
it('stop during confirmation closes after its result without dispatch',async()=>{await mount();await stage('deliver');const original=vi.mocked(mutateRaw).getMockImplementation()!;let resolve!:(v:unknown)=>void;vi.mocked(mutateRaw).mockImplementation(async(path,...rest)=>path.endsWith('/batches')?new Promise(r=>{resolve=r}) as never:original(path,...rest));const p=preview('deliver');await confirm();act(()=>window.dispatchEvent(new Event('blur')));createBatch(p);await act(async()=>resolve(structuredClone(w())));expect(mutations().map(([p])=>p.split('/').at(-1))).toEqual(['batches','close'])});
