it('generic close 409 remains GET-only across open reads and remount until exact closure',async()=>{createBatch(preview('deliver'));const ui=await mount();vi.mocked(mutateRaw).mockImplementationOnce(async(...args)=>{args[5]?.();throw new APIError('conflict or uncertain commit',409)});fireEvent.click(screen.getByRole('button',{name:'Stop sending remaining requests'}));await flush();expect(mutateRaw).toHaveBeenCalledTimes(1);expect(w().batches[0].closedAt).toBe(0);expect(screen.getByRole('button',{name:'Stop sending remaining requests'})).toBeDisabled();fireEvent.click(screen.getByRole('button',{name:'Read worklists'}));await flush();expect(screen.getByRole('button',{name:'Stop sending remaining requests'})).toBeDisabled();ui.unmount();await mount();expect(screen.getByRole('button',{name:'Stop sending remaining requests'})).toBeDisabled();expect(mutateRaw).toHaveBeenCalledTimes(1);w().batches[0].closedAt=seconds;w().batches[0].closeReason='stopped';w().revision++;fireEvent.click(screen.getByRole('button',{name:'Read worklists'}));await flush();expect(screen.queryByRole('alert')).toBeNull();expect(mutateRaw).toHaveBeenCalledTimes(1)});

