it('stopping a scheduling batch preserves approved intent and device detail allows exact cancellation only',async()=>{
 await scheduleForm();const original=vi.mocked(mutateRaw).getMockImplementation()!;let resolve!:(value:unknown)=>void;vi.mocked(mutateRaw).mockImplementation(async(path,...rest)=>path.endsWith('/schedule')?new Promise(r=>{resolve=r}) as never:original(path,...rest));await confirmSchedules();await settledScheduleRequests(2);fireEvent.click(screen.getByRole('button',{name:'Stop sending remaining requests'}));await act(async()=>resolve(await issueScheduled(0)));await settledScheduleRequests(3);await finishedScheduleRun();expect(mutations().map(([p])=>p.split('/').at(-1))).toEqual(['batches','schedule','close']);expect(w().rows[0].view!.schedule!.state).toBe('scheduled');expect(w().batches[0].items[1].state).toBe('not_dispatched');fireEvent.click(screen.getByRole('button',{name:'Read worklists'}));await flush();fireEvent.click(screen.getByRole('button',{name:`Open device: ${devices[0].name}`}));await flush();expect(screen.getByRole('button',{name:'Cancel this schedule'})).toBeEnabled();expect(screen.queryByRole('button',{name:'Approve one installation'})).toBeNull();expect(screen.queryByRole('button',{name:'Approve scheduled installation once'})).toBeNull();
 vi.mocked(mutateRaw).mockImplementation(async(path,raw)=>{expect(path).toBe(`/devices/${devices[0].id}/windows-managed-msi/cancel-schedule`);expect(JSON.parse(raw)).toEqual({scheduleDigest:w().rows[0].view!.schedule!.digest});const view=w().rows[0].view!;view.schedule={...view.schedule!,state:'canceled',canCancel:false,outcomeAt:seconds};return structuredClone(view) as never});fireEvent.click(screen.getByRole('button',{name:'Cancel this schedule'}));await flush();expect(screen.queryByRole('button',{name:'Cancel this schedule'})).toBeNull();expect(w().rows[0].view!.schedule!.state).toBe('canceled');
});
