 for(const state of ['blocked','expired'] as const){first.view!.schedule={...first.view!.schedule!,state,canCancel:false,outcomeAt:seconds};fireEvent.click(screen.getByRole('button',{name:'Read worklists'}));await flush();expect(screen.getByText('Attention: 2')).toBeVisible()}
 first.view!.schedule={...first.view!.schedule!,state:'scheduled',canCancel:true,outcomeAt:0};first.state='intervention_required';first.view!.state='intervention_required';fireEvent.click(screen.getByRole('button',{name:'Read worklists'}));await flush();expect(screen.getByText('Attention: 2')).toBeVisible();
